def calculate_S(N):
    S = 0
    N_plus_1 = N + 1
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            S += (a * b) // N_plus_1
    return S

def calculate_F(N):
    return (N**3 - N**2 + 2) / 4

N_values = [1, 2, 3, 4, 5]
results = {}

for N in N_values:
    S_N = calculate_S(N)
    F_N = calculate_F(N)
    results[N] = {'S(N)': S_N, 'F(N)': F_N, 'Match': S_N == F_N}

for N, res in results.items():
    print(f"N={N}: S(N) = {res['S(N)']}, F(N) = {res['F(N)']}, Match = {res['Match']}")

def calculate_R(N):
    R_sum = 0
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            R_sum += {a * b / (N + 1)}
    return R_sum

def target_R(N):
    # Derived from equating the required sum S(N) with the target formula
    # R(N) = (N+1)^2 * (N-1) / 2
    return (N + 1)**2 * (N - 1) / 2

# Test for N=1, 2, 3
N_values = [1, 2, 3]
for N in N_values:
    R_calc = calculate_R(N)
    R_target = target_R(N)
    print(f"N={N}: Calculated R(N) = {R_calc}, Target R(N) = {R_target}")

